+ 'var layout={title:{text:"filter → map → sorted pipeline",font:{color:"#ebe6dc",size:14}},paper_bgcolor:"rgba(0,0,0,0)",plot_bgcolor:"rgba(0,0,0,0)",font:{color:"#ebe6dc"},xaxis:{visible:false,range:[-0.05,1.1]},yaxis:{visible:false,range:[0,1]},margin:{t:50,r:20,b:20,l:20},showlegend:false,annotations:arrows};'
